  for(int u=0;u<c.n;++u)for(int j=0;j<c.parameter;++j)add(u,random_value()%c.n,weight());
 }
 return g;
}
static std::uint64_t checksum(const std::vector<std::int64_t>& d,const std::vector<int>& p) {
 std::uint64_t sum=0x5434543; for(auto x:d)sum=sum*1000003+static_cast<std::uint64_t>(x);
 for(auto x:p)sum=sum*1000033+x;
 return sum;
}

using RunFunction = void (*)(const WGraph&,std::vector<std::int64_t>&,int,int,std::vector<int>&);
#define MAKE_WRAPPERS(Suffix) \
[[gnu::noinline]] static void RunDistance##Suffix(const WGraph& g,std::vector<std::int64_t>& d,int start,int,std::vector<int>&) { Dijkstra##Suffix(g,d,start); } \
[[gnu::noinline]] static void RunPath##Suffix(const WGraph& g,std::vector<std::int64_t>& d,int start,int target,std::vector<int>& p) { Dijkstra##Suffix(g,d,start,target,p); }
