MAKE_WRAPPERS(Candidate)
#undef MAKE_WRAPPERS
// Scan the same graph in the same order before every timed variant.
static volatile std::uint64_t cache_sink;
[[gnu::noinline]] static void condition_graph(const WGraph& g) {
 std::uint64_t sum=0;
 for(const auto& edges:g)for(const auto& e:edges)sum+=static_cast<std::uint64_t>(e.w)+e.to;
 cache_sink=sum;
}
int main(int argc,char** argv) {
 if(argc==2 && std::string(argv[1])=="--list") {for(const auto& c:cases)std::puts(c.name.c_str());return 0;}
