  const auto expected=checksum(reference,{});
  std::array<std::vector<double>,3> samples;
  std::vector<std::array<int,3>> measured_orders;
  // Shared output storage avoids assigning a permanently privileged allocation
  // address to a specific variant. Allocation/cache effects are still measured
  // by the byte-identical baseline/control comparison.
  for(int round=-warmups;round<rounds;++round) {
   const auto& order=orders[(round+warmups)%orders.size()];
   if(round>=0)measured_orders.push_back(order);
   for(const int variant:order) {
    if(mode=="fresh") {std::vector<std::int64_t>().swap(d);std::vector<int>().swap(p);}
    else {d.assign(reference.begin(),reference.end());p.clear();}
