     std::fprintf(stderr,"distance mismatch: %s %s %s variant=%s round=%d\n",c.name.c_str(),api.c_str(),mode.c_str(),labels[variant],round);
     return 2;
    }
    if(round>=0)samples[variant].push_back(std::chrono::duration<double,std::nano>(end-begin).count()/batch);
   }
  }
