   auto sorted=samples[variant];std::sort(sorted.begin(),sorted.end());
   std::printf("{\"case\":\"%s\",\"api\":\"%s\",\"mode\":\"%s\",\"variant\":\"%s\",\"vertices\":%d,\"edges\":%zu,\"batch\":%d,\"rounds\":%d,\"warmups\":%d,\"median_ns\":%.4f,\"checksum\":%ju,\"samples_ns\":[",c.name.c_str(),api.c_str(),mode.c_str(),labels[variant],c.n,edges,batch,rounds,warmups,sorted[sorted.size()/2],static_cast<std::uintmax_t>(expected));
   for(std::size_t i=0;i<samples[variant].size();++i)std::printf("%s%.4f",i?",":"",samples[variant][i]);
   std::puts("]}");
  }
