static std::uint64_t checks=0;
static void require(bool v,const char *message){++checks;if(!v)throw std::runtime_error(message);}
int main(int argc,char **argv) {
 try {
    require(argc==2,"answer path argument");
    std::ios::sync_with_stdio(false);std::cin.tie(nullptr);
    int n,m,s,t;std::cin>>n>>m>>s>>t;WGraph graph(n);
    for(int i=0;i<m;++i){int u,v;std::int64_t w;std::cin>>u>>v>>w;graph[u].emplace_back(v,w);}
    require(!std::cin.fail(),"read input");
    // Independent traditional binary heap with settled-once flags, unlike the candidate radix kernel.
    using Item=std::pair<std::int64_t,int>;
    std::priority_queue<Item,std::vector<Item>,std::greater<Item>> heap;
    std::vector<std::int64_t> reference(n,INF);
    std::vector<bool> settled(n);heap.emplace(0,s);
    while(!heap.empty()) {
        const auto [d,u]=heap.top();heap.pop();if(settled[u])continue;
        settled[u]=true;reference[u]=d;
        for(const auto&e:graph[u])if(!settled[e.to])heap.emplace(d+e.w,e.to);
    }
    std::ifstream answer(argv[1]);std::int64_t official;answer>>official;
    require(!answer.fail(),"read official answer");
    require(reference[t]==(official==-1?INF:official),"reference target vs official");
    std::vector<std::int64_t> actual{123,456};Dijkstra(graph,actual,s);
    require(actual==reference,"distance overload all-distance mismatch");
    std::vector<int> path{123,456};Dijkstra(graph,actual,s,t,path);
    require(actual==reference,"path overload all-distance mismatch");
    if(reference[t]==INF)require(path.empty(),"unreachable path nonempty");
    else {
        require(!path.empty() && path.front()==s && path.back()==t,"path endpoints");
        require(path.size()<=static_cast<std::size_t>(n),"path cyclic");
        std::int64_t total=0;
        for(std::size_t i=1;i<path.size();++i) {
            require(path[i]>=0 && path[i]<n,"path vertex range");
            auto w=INF;for(const auto&e:graph[path[i-1]])if(e.to==path[i])w=std::min(w,e.w);
            require(w!=INF,"path missing edge");total+=w;
        }
        require(total==reference[t],"path cost mismatch");
    }
    std::cout<<"{\"vertices\":"<<n<<",\"edges\":"<<m<<",\"checks\":"<<checks<<"}\n";
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}
}

